.ops-rc-rule--fail .ops-rc-mark, .ops-rc-rule--fail td:nth-child(3) { color: var(--accent-error); }
@media (max-width: 640px) { .ops-legs { grid-template-columns: 1fr; } .ops-legs-arrow { display: none; } }

/* The rules browser (knowledge-base/decisions/control-tower-v3.md §16): the summary strip, tier chips, one table per
   tier, and the rule's detail as a side panel. */
.ops-rules { padding: 12px 16px; display: flex; flex-direction: column; gap: 12px; }
.ops-rules-summary { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px 18px; padding: 10px 14px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); color: var(--text-secondary); }
.ops-rules-generation { font: 700 18px var(--font-mono); color: var(--text-primary); }
.ops-rules-hash, .ops-rules-code { font: 12px var(--font-mono); color: var(--text-tertiary); }
.ops-rules-controls { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; }
.ops-rules-controls input[type="search"] { min-width: 260px; padding: 6px 10px; border-radius: 6px; border: 1px solid var(--border-secondary); background: var(--bg-secondary); color: inherit; }
