import { useEffect, useMemo, useRef, useState } from "react";
import { formatInstant, type Translator } from "@dcortex/canvas-format";
import { clampZoom, graticuleD, greatCircle, lineD, panBy, project, ringsD, viewBoxFor, zoomAt, type LonLat } from "./geo.js";
import { placeLabels } from "./labels.js";
import { isDelayed, isUncrewed, paintRank } from "./flightAttention.js";
import { alertsOf, delayEventOf, diversionOf, type OpsFlight, type StationTasks } from "./opsApi.js";

/** The Operations Control Panel map (knowledge-base/features/ops-control-panel.md §5): plain SVG over the bundled
 * Natural Earth basemap — no map library, no tiles, no egress, and nothing the CSP has to allow. The look follows
 * dcortex-gen2's ops map: a dark field with a graticule, the network as quiet dots, labelled airports, origins as a
 * square with a halo. Routes run along the great circle (drawing only); an airborne flight's position is the BFF's
 * estimate and is labelled as one. */

export interface Basemap {
  land: readonly (readonly number[])[];
  borders: readonly (readonly number[])[];
}
export interface MapStation {
  iata: string;
  position: LonLat;
}
type RenderCtx = { timezone: string; locale: string; currency: string };

const DEFAULT_ZOOM = 3;
const TASK_CATEGORY_ORDER = ["absence", "coverage", "legality", "fdp_extension", "readiness", "callout"];
const byCategoryOrder = ([a]: [string, number], [b]: [string, number]) =>
  (TASK_CATEGORY_ORDER.indexOf(a) + 1 || 99) - (TASK_CATEGORY_ORDER.indexOf(b) + 1 || 99) || a.localeCompare(b);
const total = (counts: Record<string, number>) => Object.values(counts).reduce((n, c) => n + c, 0);
const FALLBACK_SIZE = { w: 800, h: 440 };
const WHEEL_STEP = 0.5;
const SEGMENTS = 32;
const ATTENTION_LEGEND = ["short", "delayed", "cancelled", "diverted", "alert"] as const;

function pathClass(f: OpsFlight): string {
  return [
    "ops-path",
    `ops-path--${f.status}`,
    ...(f.cancelled ? ["ops-path--cancelled"] : []),
    ...(isDelayed(f) ? ["ops-path--delayed"] : []),
    ...(isUncrewed(f) ? ["ops-path--short"] : []),
    ...(paintRank(f) === 0 ? ["ops-path--quiet"] : []),
    ...(f.touchesBase ? ["ops-path--base"] : []),
  ].join(" ");
}

/** Route width and dash in screen pixels: what needs attention is drawn heavier than the quiet network. */
function pathStroke(f: OpsFlight): { width: number; dash?: string } {
  if (isUncrewed(f)) return { width: 2.4, dash: "0.1 4.5" };
  if (f.cancelled) return { width: 1.8, dash: "5 4" };
  if (paintRank(f) > 0) return { width: 2 };
  return { width: f.touchesBase ? 1.4 : 1 };
}

/** A person glyph in map units, centred on (x, y): head and shoulders, the crew badge's icon. */
function CrewGlyph({ x, y, px }: { x: number; y: number; px: number }) {
  return (
    <g data-testid="ops-crew-icon" className="ops-crew-icon">
      <circle cx={x} cy={y - 1.8 * px} r={1.7 * px} />
      <path d={`M${x - 3.2 * px} ${y + 3.6 * px}a${3.2 * px} ${3.2 * px} 0 0 1 ${6.4 * px} 0Z`} />
    </g>
  );
}

export function OpsMap({
  t, flights, center, baseIata, basemap, onSelect, stations = [], asOf, renderCtx, stationTasks = [], unplacedTasks = {}, places, unfilteredCount,
}: {
  t: Translator;
  flights: readonly OpsFlight[];
  center: LonLat;
  baseIata: string | undefined;
  basemap: Basemap | undefined;
  onSelect: (f: OpsFlight) => void;
  /** The tenant's whole network, drawn as quiet context. */
  stations?: readonly MapStation[];
  asOf?: string;
  renderCtx?: RenderCtx;
  /** The open tasks the viewer may read, per station; a station the map cannot place counts in the header. */
  stationTasks?: readonly StationTasks[];
  unplacedTasks?: Record<string, number>;
  /** IATA → "City — Airport name", for the markers' hover titles. */
  places?: ReadonlyMap<string, string>;
  /** The window's flight count before an attention filter; given only while one is on. */
  unfilteredCount?: number;
}) {
  const [view, setView] = useState({ center, zoom: DEFAULT_ZOOM });
  const [size, setSize] = useState(FALLBACK_SIZE);
  const drag = useRef<{ x: number; y: number } | undefined>(undefined);
  const svgRef = useRef<SVGSVGElement>(null);
  const aspect = size.h / size.w;

  useEffect(() => setView({ center, zoom: DEFAULT_ZOOM }), [center.lat, center.lon]); // eslint-disable-line react-hooks/exhaustive-deps

  // The viewBox takes the element's own aspect, so one screen pixel is the same distance across and down.
  useEffect(() => {
    const svg = svgRef.current;
    if (!svg || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(([entry]) => {
      const { width, height } = entry!.contentRect;
      if (width > 0 && height > 0) setSize({ w: width, h: height });
    });
    observer.observe(svg);
    return () => observer.disconnect();
  }, []);

  // Wheel zoom about the cursor. A native listener, because React's wheel handler is passive and could not stop the
  // page from scrolling underneath the map.
  useEffect(() => {
    const svg = svgRef.current;
    if (!svg) return;
    const onWheel = (e: WheelEvent) => {
      e.preventDefault();
      const rect = svg.getBoundingClientRect();
      const w = rect.width || FALLBACK_SIZE.w;
      const h = rect.height || FALLBACK_SIZE.h;
      const cursor = { fx: (e.clientX - rect.left) / w, fy: (e.clientY - rect.top) / h };
      setView((v) => {
        const zoom = clampZoom(v.zoom + (e.deltaY < 0 ? WHEEL_STEP : -WHEEL_STEP));
        return zoom === v.zoom ? v : { zoom, center: zoomAt({ ...v, aspect: h / w }, zoom, cursor) };
      });
    };
    svg.addEventListener("wheel", onWheel, { passive: false });
    return () => svg.removeEventListener("wheel", onWheel);
  }, []);

  const land = useMemo(() => (basemap ? ringsD(basemap.land) : undefined), [basemap]);
  const borders = useMemo(() => (basemap ? ringsD(basemap.borders).replace(/Z/g, "") : undefined), [basemap]);
  const graticule = useMemo(() => graticuleD(10), []);
  // A diverted flight is drawn to where it went, when the network can place that airport.
  const endOf = useMemo(() => {
    const placed = new Map(stations.map((s) => [s.iata, s.position]));
    return (f: OpsFlight): { iata: string; position?: LonLat } => {
      const to = diversionOf(f)?.to;
      const position = to ? placed.get(to) : undefined;
      return to && position ? { iata: to, position } : f.destination;
    };
  }, [stations]);
  const routes = useMemo(
    () =>
      [...flights].sort((a, b) => paintRank(a) - paintRank(b)).flatMap((f) => {
        const end = endOf(f);
        if (!f.origin.position || !end.position) return [];
        const points = greatCircle(f.origin.position, end.position, SEGMENTS);
        // A badge sits 40% of the way from the origin, so a flight and its return (one great circle) keep theirs apart.
        return [{
          f,
          d: lineD(points),
          mid: project(points[Math.floor(points.length / 2)]!),
          badge: project(points[Math.floor(points.length * 0.4)]!),
          crewAt: project(points[Math.floor(points.length * 0.6)]!),
          end: { iata: end.iata, ...project(end.position) },
        }];
      }),
    [flights, endOf],
  );
  const origins = useMemo(() => new Set(routes.map((r) => r.f.origin.iata)), [routes]);
  const airports = useMemo(() => {
    const byIata = new Map<string, LonLat>();
    for (const f of flights) for (const p of [f.origin, endOf(f)]) if (p.position) byIata.set(p.iata, p.position);
    const baseStation = stations.find((s) => s.iata === baseIata);
    if (baseStation && !byIata.has(baseStation.iata)) byIata.set(baseStation.iata, baseStation.position);
    return [...byIata].map(([iata, position]) => ({ iata, ...project(position) }));
  }, [flights, stations, baseIata, endOf]);

  const taskBadges = useMemo(() => {
    const placed = new Map<string, LonLat>(stations.map((s) => [s.iata, s.position]));
    for (const f of flights) for (const p of [f.origin, f.destination]) if (p.position) placed.set(p.iata, p.position);
    return stationTasks.flatMap((s) => {
      const position = placed.get(s.iata);
      return position ? [{ ...s, ...project(position) }] : [];
    });
  }, [stationTasks, stations, flights]);
  const tasksNotOnMap = useMemo(() => {
    const placedIatas = new Set(taskBadges.map((b) => b.iata));
    return total(unplacedTasks) + stationTasks.filter((s) => !placedIatas.has(s.iata)).reduce((n, s) => n + total(s.openTasks), 0);
  }, [taskBadges, stationTasks, unplacedTasks]);

  const vb = viewBoxFor({ center: view.center, zoom: view.zoom, aspect });
  const px = vb.width / size.w; // one screen pixel in map units: strokes, markers and labels keep their screen size

  // Labels are placed in screen pixels (labels.ts) and drawn back in map units.
  const labels = useMemo(
    () =>
      placeLabels(
        airports.map((a) => ({ iata: a.iata, sx: (a.x - vb.x) / px, sy: (a.y - vb.y) / px, strong: a.iata === baseIata || origins.has(a.iata) })),
        { width: size.w, height: size.h },
      ).map((l) => ({ iata: l.iata, strong: l.strong, x: vb.x + l.lx * px, y: vb.y + l.ly * px, anchor: l.anchor })),
    [airports, origins, baseIata, vb.x, vb.y, px, size.w, size.h],
  );

  const zoomBy = (step: number) => setView((v) => ({ ...v, zoom: clampZoom(v.zoom + step) }));
  const flightName = (f: OpsFlight) => `${f.carrier}${f.flightNumber}`;

  return (
    <div className="ops-map" data-testid="ops-map">
      <div className="ops-map-head" data-testid="ops-map-head">
        <span>
          {unfilteredCount === undefined
            ? t("ops.map.head", { flights: routes.length, stations: stations.length })
            : t("ops.map.headFiltered", { flights: routes.length, total: unfilteredCount, stations: stations.length })}
        </span>
        {tasksNotOnMap > 0 && <span className="ops-map-asof">{t("ops.map.unplacedTasks", { n: tasksNotOnMap })}</span>}
        {asOf && renderCtx && <span className="ops-map-asof">{t("ops.map.asOf", { time: formatInstant(asOf, renderCtx) })}</span>}
      </div>
      <div className="ops-map-controls">
        <button type="button" data-testid="ops-zoom-in" aria-label={t("ops.map.zoomIn")} onClick={() => zoomBy(1)}>
          +
        </button>
        <button type="button" data-testid="ops-zoom-out" aria-label={t("ops.map.zoomOut")} onClick={() => zoomBy(-1)}>
          −
        </button>
        <button type="button" data-testid="ops-zoom-reset" onClick={() => setView({ center, zoom: DEFAULT_ZOOM })}>
          {t("ops.map.recentre", { base: baseIata ?? "" })}
        </button>
      </div>
      <svg
        ref={svgRef}
        data-testid="ops-map-svg"
        className="ops-map-svg"
        role="img"
        aria-label={t("ops.map.label")}
        viewBox={`${vb.x} ${vb.y} ${vb.width} ${vb.height}`}
        onPointerDown={(e) => {
          drag.current = { x: e.clientX, y: e.clientY };
        }}
        onPointerMove={(e) => {
          if (!drag.current) return;
          const widthPx = svgRef.current?.getBoundingClientRect().width || size.w;
          const delta = { dx: e.clientX - drag.current.x, dy: e.clientY - drag.current.y };
          drag.current = { x: e.clientX, y: e.clientY };
          setView((v) => ({ ...v, center: panBy(v.center, delta, { zoom: v.zoom, widthPx }) }));
        }}
        onPointerUp={() => {
          drag.current = undefined;
        }}
        onPointerLeave={() => {
          drag.current = undefined;
        }}
      >
        <path data-testid="ops-graticule" className="ops-graticule" d={graticule} strokeWidth={0.6 * px} />
        {land && <path data-testid="ops-land" className="ops-land" d={land} strokeWidth={0.7 * px} />}
        {borders && <path data-testid="ops-borders" className="ops-borders" d={borders} strokeWidth={0.6 * px} strokeDasharray={`${2 * px} ${2 * px}`} />}
        {stations.map((s) => {
          const p = project(s.position);
          return <circle key={s.iata} data-testid="ops-station-dot" data-iata={s.iata} className="ops-station-dot" cx={p.x} cy={p.y} r={2.2 * px} />;
        })}
        {routes.map(({ f, d }) => {
          const stroke = pathStroke(f);
          const title = `${flightName(f)} ${f.origin.iata} → ${f.destination.iata}`;
          return (
            <g key={f.legId} className="ops-route">
              <path
                data-testid="ops-flight-path"
                data-leg={f.legId}
                className={pathClass(f)}
                d={d}
                strokeWidth={stroke.width * px}
                {...(stroke.dash ? { strokeDasharray: stroke.dash.split(" ").map((n) => Number(n) * px).join(" ") } : {})}
                onClick={() => onSelect(f)}
              >
                <title>{title}</title>
              </path>
              <path data-testid="ops-flight-hit" data-leg={f.legId} className="ops-flight-hit" d={d} strokeWidth={12 * px} onClick={() => onSelect(f)}>
                <title>{title}</title>
              </path>
            </g>
          );
        })}
        {routes.map(({ f, end }) => {
          const diversion = diversionOf(f);
          if (!diversion) return null;
          return (
            <g key={f.legId} data-testid="ops-event-diversion" data-leg={f.legId} data-at={end.iata} className="ops-event ops-event--diversion" onClick={() => onSelect(f)}>
              <path d={`M${end.x} ${end.y - 7 * px}L${end.x + 7 * px} ${end.y}L${end.x} ${end.y + 7 * px}L${end.x - 7 * px} ${end.y}Z`} strokeWidth={1.5 * px} />
              <title>{diversion.to ? t("ops.map.divertedTitle", { flight: flightName(f), to: diversion.to }) : t("ops.map.divertedUnknownTitle", { flight: flightName(f) })}</title>
            </g>
          );
        })}
        {routes.map(({ f, crewAt }) => {
          if (!isUncrewed(f)) return null;
          const n = f.staffing?.short ?? 0;
          return (
            <g key={f.legId} data-testid="ops-event-short" data-leg={f.legId} className="ops-event ops-event--short" onClick={() => onSelect(f)}>
              <rect x={crewAt.x - 11 * px} y={crewAt.y - 6.5 * px} width={22 * px} height={13 * px} rx={6.5 * px} strokeWidth={1 * px} />
              <CrewGlyph x={crewAt.x - 4.5 * px} y={crewAt.y} px={px} />
              <text x={crewAt.x + 4.5 * px} y={crewAt.y + 3.5 * px} fontSize={9.5 * px} textAnchor="middle">
                {n}
              </text>
              <title>{t("ops.map.shortTitle", { flight: flightName(f), n })}</title>
            </g>
          );
        })}
        {routes.map(({ f, mid }) => {
          const alerts = alertsOf(f);
          if (alerts.length === 0) return null;
          const y = mid.y - 12 * px;
          return (
            <g key={f.legId} data-testid="ops-event-alert" data-leg={f.legId} className="ops-event ops-event--alert" onClick={() => onSelect(f)}>
              <path d={`M${mid.x} ${y - 6 * px}L${mid.x + 6 * px} ${y + 5 * px}L${mid.x - 6 * px} ${y + 5 * px}Z`} strokeWidth={1 * px} />
              <text x={mid.x} y={y + 3.5 * px} fontSize={8 * px} textAnchor="middle">
                {alerts.length}
              </text>
              <title>{t("ops.map.alertTitle", { flight: flightName(f), alerts: alerts.map((a) => a.label).join("; ") })}</title>
            </g>
          );
        })}
        {routes.map(({ f, badge: mid }) => {
          const delay = delayEventOf(f);
          return f.cancelled ? (
            <g key={f.legId} data-testid="ops-event-cancelled" data-leg={f.legId} className="ops-event ops-event--cancelled" onClick={() => onSelect(f)}>
              <path d={`M${mid.x - 4 * px} ${mid.y - 4 * px}L${mid.x + 4 * px} ${mid.y + 4 * px}M${mid.x - 4 * px} ${mid.y + 4 * px}L${mid.x + 4 * px} ${mid.y - 4 * px}`} strokeWidth={2 * px} />
              <title>{t("ops.map.cancelledTitle", { flight: flightName(f) })}</title>
            </g>
          ) : delay ? (
            <g key={f.legId} data-testid="ops-event-delay" data-leg={f.legId} className={`ops-event ops-event--delay${delay.recovering ? " ops-event--recovering" : ""}`} onClick={() => onSelect(f)}>
              <circle cx={mid.x} cy={mid.y} r={4 * px} />
              <text x={mid.x + 6 * px} y={mid.y + 3.5 * px} fontSize={10 * px} strokeWidth={3 * px}>
                {t(delay.recovering ? "ops.map.recoveringBadge" : "ops.map.delayBadge", { n: delay.minutes })}
              </text>
              {delay.recovering && <title>{t("ops.map.recoveringTitle", { flight: flightName(f), n: delay.minutes })}</title>}
            </g>
          ) : null;
        })}
        {airports.map((a) => (
          <g key={a.iata} data-testid="ops-airport" data-iata={a.iata} className={a.iata === baseIata ? "ops-airport ops-airport--base" : "ops-airport"}>
            {origins.has(a.iata) ? (
              <g data-testid="ops-origin" data-iata={a.iata}>
                <circle className="ops-halo" cx={a.x} cy={a.y} r={(a.iata === baseIata ? 16 : 11) * px} strokeWidth={0.9 * px} />
                <rect className="ops-origin-mark" x={a.x - 3.5 * px} y={a.y - 3.5 * px} width={7 * px} height={7 * px} />
              </g>
            ) : (
              <circle className="ops-dest-mark" cx={a.x} cy={a.y} r={3.5 * px} />
            )}
            <title>{places?.get(a.iata) ? `${a.iata} — ${places.get(a.iata)}` : a.iata}</title>
          </g>
        ))}
        {flights.flatMap((f) => {
          if (!f.estimatedPosition) return [];
          const p = project(f.estimatedPosition);
          return [
            <g key={f.legId} data-testid="ops-position" data-leg={f.legId} className="ops-position" onClick={() => onSelect(f)}>
              <circle cx={p.x} cy={p.y} r={4.5 * px} strokeWidth={1.2 * px} />
              <title>{t("ops.map.estimatedPosition", { flight: flightName(f) })}</title>
            </g>,
          ];
        })}
        {taskBadges.map((b) => (
          <g key={b.iata} data-testid="ops-station-tasks" data-iata={b.iata} className="ops-station-tasks">
            <rect x={b.x + 6 * px} y={b.y + 5 * px} width={16 * px} height={11 * px} rx={3 * px} strokeWidth={1 * px} />
            <text x={b.x + 14 * px} y={b.y + 13.5 * px} fontSize={8.5 * px} textAnchor="middle">
              {total(b.openTasks)}
            </text>
            <title>
              {`${b.iata}: ${Object.entries(b.openTasks)
                .sort(byCategoryOrder)
                .map(([category, n]) => `${t(`ops.task.${category}`)} ${n}`)
                .join(" · ")}`}
            </title>
          </g>
        ))}
        {labels.map((l) => (
          <text
            key={l.iata}
            data-testid="ops-label"
            className={l.strong ? "ops-label ops-label--strong" : "ops-label"}
            x={l.x}
            y={l.y}
            textAnchor={l.anchor}
            fontSize={11 * px}
            strokeWidth={3 * px}
          >
            {l.iata}
          </text>
        ))}
      </svg>
      <span className="ops-map-credit" data-testid="ops-map-credit">
        {t("ops.map.credit")}
      </span>
      <div className="ops-legend" data-testid="ops-legend">
        <span className="ops-legend-title">{t("ops.legend.attention")}</span>
        <ul className="ops-legend-group" aria-label={t("ops.legend.attention")}>
          {ATTENTION_LEGEND.map((k) => (
            <li key={k} className={`ops-legend--${k}`}>
              {k === "short" ? <svg className="ops-legend-crew" viewBox="-6 -6 12 12" aria-hidden="true"><CrewGlyph x={0} y={0} px={1.1} /></svg> : null}
              {t(`ops.legend.${k}`)}
            </li>
          ))}
        </ul>
        <ul className="ops-legend-group ops-legend-group--quiet">
          <li className="ops-legend--other">{t("ops.legend.other")}</li>
        </ul>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { formatInstant, type Translator } from "@dcortex/canvas-format";
import { clampZoom, graticuleD, greatCircle, lineD, panBy, project, ringsD, viewBoxFor, zoomAt, type LonLat } from "./geo.js";
import { placeLabels } from "./labels.js";
import { isDelayed, isUncrewed, paintRank } from "./flightAttention.js";
import { alertsOf, delayEventOf, diversionOf, type OpsFlight, type StationTasks } from "./opsApi.js";

/** The Operations Control Panel map (knowledge-base/features/ops-control-panel.md §5): plain SVG over the bundled
 * Natural Earth basemap — no map library, no tiles, no egress, and nothing the CSP has to allow. The look follows
 * dcortex-gen2's ops map: a dark field with a graticule, the network as quiet dots, labelled airports, origins as a
 * square with a halo. Routes run along the great circle (drawing only); an airborne flight's position is the BFF's
 * estimate and is labelled as one. */

export interface Basemap {
  land: readonly (readonly number[])[];
  borders: readonly (readonly number[])[];
}
export interface MapStation {
  iata: string;
  position: LonLat;
}
type RenderCtx = { timezone: string; locale: string; currency: string };

const DEFAULT_ZOOM = 3;
const TASK_CATEGORY_ORDER = ["absence", "coverage", "legality", "fdp_extension", "readiness", "callout"];
const byCategoryOrder = ([a]: [string, number], [b]: [string, number]) =>
  (TASK_CATEGORY_ORDER.indexOf(a) + 1 || 99) - (TASK_CATEGORY_ORDER.indexOf(b) + 1 || 99) || a.localeCompare(b);
const total = (counts: Record<string, number>) => Object.values(counts).reduce((n, c) => n + c, 0);
const FALLBACK_SIZE = { w: 800, h: 440 };
const WHEEL_STEP = 0.5;
const SEGMENTS = 32;
const ATTENTION_LEGEND = ["short", "delayed", "cancelled", "diverted", "alert"] as const;

function pathClass(f: OpsFlight): string {
  return [
    "ops-path",
    `ops-path--${f.status}`,
    ...(f.cancelled ? ["ops-path--cancelled"] : []),
    ...(isDelayed(f) ? ["ops-path--delayed"] : []),
    ...(isUncrewed(f) ? ["ops-path--short"] : []),
    ...(paintRank(f) === 0 ? ["ops-path--quiet"] : []),
    ...(f.touchesBase ? ["ops-path--base"] : []),
  ].join(" ");
}

/** Route width and dash in screen pixels: what needs attention is drawn heavier than the quiet network. */
function pathStroke(f: OpsFlight): { width: number; dash?: string } {
  if (isUncrewed(f)) return { width: 2.4, dash: "0.1 4.5" };
  if (f.cancelled) return { width: 1.8, dash: "5 4" };
  if (paintRank(f) > 0) return { width: 2 };
  return { width: f.touchesBase ? 1.4 : 1 };
}

/** A person glyph in map units, centred on (x, y): head and shoulders, the crew badge's icon. */
function CrewGlyph({ x, y, px }: { x: number; y: number; px: number }) {
  return (
    <g data-testid="ops-crew-icon" className="ops-crew-icon">
      <circle cx={x} cy={y - 1.8 * px} r={1.7 * px} />
      <path d={`M${x - 3.2 * px} ${y + 3.6 * px}a${3.2 * px} ${3.2 * px} 0 0 1 ${6.4 * px} 0Z`} />
    </g>
  );
}

export function OpsMap({
  t, flights, center, baseIata, basemap, onSelect, stations = [], asOf, renderCtx, stationTasks = [], unplacedTasks = {}, places, unfilteredCount,
}: {
  t: Translator;
  flights: readonly OpsFlight[];
  center: LonLat;
  baseIata: string | undefined;
  basemap: Basemap | undefined;
  onSelect: (f: OpsFlight) => void;
  /** The tenant's whole network, drawn as quiet context. */
  stations?: readonly MapStation[];
  asOf?: string;
  renderCtx?: RenderCtx;
  /** The open tasks the viewer may read, per station; a station the map cannot place counts in the header. */
  stationTasks?: readonly StationTasks[];
  unplacedTasks?: Record<string, number>;
  /** IATA → "City — Airport name", for the markers' hover titles. */
  places?: ReadonlyMap<string, string>;
  /** The window's flight count before an attention filter; given only while one is on. */
  unfilteredCount?: number;
}) {
  const [view, setView] = useState({ center, zoom: DEFAULT_ZOOM });
  const [size, setSize] = useState(FALLBACK_SIZE);
  const drag = useRef<{ x: number; y: number } | undefined>(undefined);
  const svgRef = useRef<SVGSVGElement>(null);
  const aspect = size.h / size.w;

  useEffect(() => setView({ center, zoom: DEFAULT_ZOOM }), [center.lat, center.lon]); // eslint-disable-line react-hooks/exhaustive-deps

  // The viewBox takes the element's own aspect, so one screen pixel is the same distance across and down.
  useEffect(() => {
    const svg = svgRef.current;
    if (!svg || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(([entry]) => {
      const { width, height } = entry!.contentRect;
      if (width > 0 && height > 0) setSize({ w: width, h: height });
    });
    observer.observe(svg);
    return () => observer.disconnect();
  }, []);

  // Wheel zoom about the cursor. A native listener, because React's wheel handler is passive and could not stop the
  // page from scrolling underneath the map.
  useEffect(() => {
    const svg = svgRef.current;
    if (!svg) return;
    const onWheel = (e: WheelEvent) => {
      e.preventDefault();
      const rect = svg.getBoundingClientRect();
      const w = rect.width || FALLBACK_SIZE.w;
      const h = rect.height || FALLBACK_SIZE.h;
      const cursor = { fx: (e.clientX - rect.left) / w, fy: (e.clientY - rect.top) / h };
      setView((v) => {
        const zoom = clampZoom(v.zoom + (e.deltaY < 0 ? WHEEL_STEP : -WHEEL_STEP));
        return zoom === v.zoom ? v : { zoom, center: zoomAt({ ...v, aspect: h / w }, zoom, cursor) };
      });
    };
    svg.addEventListener("wheel", onWheel, { passive: false });
    return () => svg.removeEventListener("wheel", onWheel);
  }, []);

  const land = useMemo(() => (basemap ? ringsD(basemap.land) : undefined), [basemap]);
  const borders = useMemo(() => (basemap ? ringsD(basemap.borders).replace(/Z/g, "") : undefined), [basemap]);
  const graticule = useMemo(() => graticuleD(10), []);
  // A diverted flight is drawn to where it went, when the network can place that airport.
  const endOf = useMemo(() => {
    const placed = new Map(stations.map((s) => [s.iata, s.position]));
    return (f: OpsFlight): { iata: string; position?: LonLat } => {
      const to = diversionOf(f)?.to;
      const position = to ? placed.get(to) : undefined;
      return to && position ? { iata: to, position } : f.destination;
    };
  }, [stations]);
  const routes = useMemo(
    () =>
      [...flights].sort((a, b) => paintRank(a) - paintRank(b)).flatMap((f) => {
        const end = endOf(f);
        if (!f.origin.position || !end.position) return [];
        const points = greatCircle(f.origin.position, end.position, SEGMENTS);
        // A badge sits 40% of the way from the origin, so a flight and its return (one great circle) keep theirs apart.
        return [{
          f,
          d: lineD(points),
          mid: project(points[Math.floor(points.length / 2)]!),
          badge: project(points[Math.floor(points.length * 0.4)]!),
          crewAt: project(points[Math.floor(points.length * 0.6)]!),
          end: { iata: end.iata, ...project(end.position) },
        }];
      }),
    [flights, endOf],
  );
  const origins = useMemo(() => new Set(routes.map((r) => r.f.origin.iata)), [routes]);
  const airports = useMemo(() => {
    const byIata = new Map<string, LonLat>();
    for (const f of flights) for (const p of [f.origin, endOf(f)]) if (p.position) byIata.set(p.iata, p.position);
    const baseStation = stations.find((s) => s.iata === baseIata);
    if (baseStation && !byIata.has(baseStation.iata)) byIata.set(baseStation.iata, baseStation.position);
    return [...byIata].map(([iata, position]) => ({ iata, ...project(position) }));
  }, [flights, stations, baseIata, endOf]);

  const taskBadges = useMemo(() => {
    const placed = new Map<string, LonLat>(stations.map((s) => [s.iata, s.position]));
    for (const f of flights) for (const p of [f.origin, f.destination]) if (p.position) placed.set(p.iata, p.position);
    return stationTasks.flatMap((s) => {
      const position = placed.get(s.iata);
      return position ? [{ ...s, ...project(position) }] : [];
    });
  }, [stationTasks, stations, flights]);
  const tasksNotOnMap = useMemo(() => {
    const placedIatas = new Set(taskBadges.map((b) => b.iata));
    return total(unplacedTasks) + stationTasks.filter((s) => !placedIatas.has(s.iata)).reduce((n, s) => n + total(s.openTasks), 0);
  }, [taskBadges, stationTasks, unplacedTasks]);

  const vb = viewBoxFor({ center: view.center, zoom: view.zoom, aspect });
  const px = vb.width / size.w; // one screen pixel in map units: strokes, markers and labels keep their screen size

  // Labels are placed in screen pixels (labels.ts) and drawn back in map units.
  const labels = useMemo(
    () =>
      placeLabels(
        airports.map((a) => ({ iata: a.iata, sx: (a.x - vb.x) / px, sy: (a.y - vb.y) / px, strong: a.iata === baseIata || origins.has(a.iata) })),
        { width: size.w, height: size.h },
      ).map((l) => ({ iata: l.iata, strong: l.strong, x: vb.x + l.lx * px, y: vb.y + l.ly * px, anchor: l.anchor })),
    [airports, origins, baseIata, vb.x, vb.y, px, size.w, size.h],
  );

  const zoomBy = (step: number) => setView((v) => ({ ...v, zoom: clampZoom(v.zoom + step) }));
  const flightName = (f: OpsFlight) => `${f.carrier}${f.flightNumber}`;

  return (
    <div className="ops-map" data-testid="ops-map">
      <div className="ops-map-head" data-testid="ops-map-head">
        <span>
          {unfilteredCount === undefined
            ? t("ops.map.head", { flights: routes.length, stations: stations.length })
            : t("ops.map.headFiltered", { flights: routes.length, total: unfilteredCount, stations: stations.length })}
        </span>
        {tasksNotOnMap > 0 && <span className="ops-map-asof">{t("ops.map.unplacedTasks", { n: tasksNotOnMap })}</span>}
        {asOf && renderCtx && <span className="ops-map-asof">{t("ops.map.asOf", { time: formatInstant(asOf, renderCtx) })}</span>}
      </div>
      <div className="ops-map-controls">
        <button type="button" data-testid="ops-zoom-in" aria-label={t("ops.map.zoomIn")} onClick={() => zoomBy(1)}>
          +
        </button>
        <button type="button" data-testid="ops-zoom-out" aria-label={t("ops.map.zoomOut")} onClick={() => zoomBy(-1)}>
          −
        </button>
        <button type="button" data-testid="ops-zoom-reset" onClick={() => setView({ center, zoom: DEFAULT_ZOOM })}>
          {t("ops.map.recentre", { base: baseIata ?? "" })}
        </button>
      </div>
      <svg
        ref={svgRef}
        data-testid="ops-map-svg"
        className="ops-map-svg"
        role="img"
        aria-label={t("ops.map.label")}
        viewBox={`${vb.x} ${vb.y} ${vb.width} ${vb.height}`}
        onPointerDown={(e) => {
          drag.current = { x: e.clientX, y: e.clientY };
        }}
        onPointerMove={(e) => {
          if (!drag.current) return;
          const widthPx = svgRef.current?.getBoundingClientRect().width || size.w;
          const delta = { dx: e.clientX - drag.current.x, dy: e.clientY - drag.current.y };
          drag.current = { x: e.clientX, y: e.clientY };
          setView((v) => ({ ...v, center: panBy(v.center, delta, { zoom: v.zoom, widthPx }) }));
        }}
        onPointerUp={() => {
          drag.current = undefined;
        }}
        onPointerLeave={() => {
          drag.current = undefined;
        }}
      >
        <path data-testid="ops-graticule" className="ops-graticule" d={graticule} strokeWidth={0.6 * px} />
        {land && <path data-testid="ops-land" className="ops-land" d={land} strokeWidth={0.7 * px} />}
        {borders && <path data-testid="ops-borders" className="ops-borders" d={borders} strokeWidth={0.6 * px} strokeDasharray={`${2 * px} ${2 * px}`} />}
        {stations.map((s) => {
          const p = project(s.position);
          return <circle key={s.iata} data-testid="ops-station-dot" data-iata={s.iata} className="ops-station-dot" cx={p.x} cy={p.y} r={2.2 * px} />;
        })}
        {routes.map(({ f, d }) => {
          const stroke = pathStroke(f);
          const title = `${flightName(f)} ${f.origin.iata} → ${f.destination.iata}`;
          return (
            <g key={f.legId} className="ops-route">
              <path
                data-testid="ops-flight-path"
                data-leg={f.legId}
                className={pathClass(f)}
                d={d}
                strokeWidth={stroke.width * px}
                {...(stroke.dash ? { strokeDasharray: stroke.dash.split(" ").map((n) => Number(n) * px).join(" ") } : {})}
                onClick={() => onSelect(f)}
              >
                <title>{title}</title>
              </path>
              <path data-testid="ops-flight-hit" data-leg={f.legId} className="ops-flight-hit" d={d} strokeWidth={12 * px} onClick={() => onSelect(f)}>
                <title>{title}</title>
              </path>
            </g>
          );
        })}
        {routes.map(({ f, end }) => {
          const diversion = diversionOf(f);
          if (!diversion) return null;
          return (
            <g key={f.legId} data-testid="ops-event-diversion" data-leg={f.legId} data-at={end.iata} className="ops-event ops-event--diversion" onClick={() => onSelect(f)}>
              <path d={`M${end.x} ${end.y - 7 * px}L${end.x + 7 * px} ${end.y}L${end.x} ${end.y + 7 * px}L${end.x - 7 * px} ${end.y}Z`} strokeWidth={1.5 * px} />
              <title>{diversion.to ? t("ops.map.divertedTitle", { flight: flightName(f), to: diversion.to }) : t("ops.map.divertedUnknownTitle", { flight: flightName(f) })}</title>
            </g>
          );
        })}
        {routes.map(({ f, crewAt }) => {
          if (!isUncrewed(f)) return null;
          const n = f.staffing?.short ?? 0;
          return (
            <g key={f.legId} data-testid="ops-event-short" data-leg={f.legId} className="ops-event ops-event--short" onClick={() => onSelect(f)}>
              <rect x={crewAt.x - 11 * px} y={crewAt.y - 6.5 * px} width={22 * px} height={13 * px} rx={6.5 * px} strokeWidth={1 * px} />
              <CrewGlyph x={crewAt.x - 4.5 * px} y={crewAt.y} px={px} />
              <text x={crewAt.x + 4.5 * px} y={crewAt.y + 3.5 * px} fontSize={9.5 * px} textAnchor="middle">
                {n}
              </text>
              <title>{t("ops.map.shortTitle", { flight: flightName(f), n })}</title>
            </g>
          );
        })}
        {routes.map(({ f, mid }) => {
          const alerts = alertsOf(f);
          if (alerts.length === 0) return null;
          const y = mid.y - 12 * px;
          return (
            <g key={f.legId} data-testid="ops-event-alert" data-leg={f.legId} className="ops-event ops-event--alert" onClick={() => onSelect(f)}>
              <path d={`M${mid.x} ${y - 6 * px}L${mid.x + 6 * px} ${y + 5 * px}L${mid.x - 6 * px} ${y + 5 * px}Z`} strokeWidth={1 * px} />
              <text x={mid.x} y={y + 3.5 * px} fontSize={8 * px} textAnchor="middle">
                {alerts.length}
              </text>
              <title>{t("ops.map.alertTitle", { flight: flightName(f), alerts: alerts.map((a) => a.label).join("; ") })}</title>
            </g>
          );
        })}
        {routes.map(({ f, badge: mid }) => {
          const delay = delayEventOf(f);
          return f.cancelled ? (
            <g key={f.legId} data-testid="ops-event-cancelled" data-leg={f.legId} className="ops-event ops-event--cancelled" onClick={() => onSelect(f)}>
              <path d={`M${mid.x - 4 * px} ${mid.y - 4 * px}L${mid.x + 4 * px} ${mid.y + 4 * px}M${mid.x - 4 * px} ${mid.y + 4 * px}L${mid.x + 4 * px} ${mid.y - 4 * px}`} strokeWidth={2 * px} />
              <title>{t("ops.map.cancelledTitle", { flight: flightName(f) })}</title>
            </g>
          ) : delay ? (
            <g key={f.legId} data-testid="ops-event-delay" data-leg={f.legId} className={`ops-event ops-event--delay${delay.recovering ? " ops-event--recovering" : ""}`} onClick={() => onSelect(f)}>
              <circle cx={mid.x} cy={mid.y} r={4 * px} />
              <text x={mid.x + 6 * px} y={mid.y + 3.5 * px} fontSize={10 * px} strokeWidth={3 * px}>
                {t(delay.recovering ? "ops.map.recoveringBadge" : "ops.map.delayBadge", { n: delay.minutes })}
              </text>
              {delay.recovering && <title>{t("ops.map.recoveringTitle", { flight: flightName(f), n: delay.minutes })}</title>}
            </g>
          ) : null;
        })}
        {airports.map((a) => (
          <g key={a.iata} data-testid="ops-airport" data-iata={a.iata} className={a.iata === baseIata ? "ops-airport ops-airport--base" : "ops-airport"}>
            {origins.has(a.iata) ? (
              <g data-testid="ops-origin" data-iata={a.iata}>
                <circle className="ops-halo" cx={a.x} cy={a.y} r={(a.iata === baseIata ? 16 : 11) * px} strokeWidth={0.9 * px} />
                <rect className="ops-origin-mark" x={a.x - 3.5 * px} y={a.y - 3.5 * px} width={7 * px} height={7 * px} />
              </g>
            ) : (
              <circle className="ops-dest-mark" cx={a.x} cy={a.y} r={3.5 * px} />
            )}
            <title>{places?.get(a.iata) ? `${a.iata} — ${places.get(a.iata)}` : a.iata}</title>
          </g>
        ))}
        {flights.flatMap((f) => {
          if (!f.estimatedPosition) return [];
          const p = project(f.estimatedPosition);
          return [
            <g key={f.legId} data-testid="ops-position" data-leg={f.legId} className="ops-position" onClick={() => onSelect(f)}>
              <circle cx={p.x} cy={p.y} r={4.5 * px} strokeWidth={1.2 * px} />
              <title>{t("ops.map.estimatedPosition", { flight: flightName(f) })}</title>
            </g>,
          ];
        })}
        {taskBadges.map((b) => (
          <g key={b.iata} data-testid="ops-station-tasks" data-iata={b.iata} className="ops-station-tasks">
            <rect x={b.x + 6 * px} y={b.y + 5 * px} width={16 * px} height={11 * px} rx={3 * px} strokeWidth={1 * px} />
            <text x={b.x + 14 * px} y={b.y + 13.5 * px} fontSize={8.5 * px} textAnchor="middle">
              {total(b.openTasks)}
            </text>
            <title>
              {`${b.iata}: ${Object.entries(b.openTasks)
                .sort(byCategoryOrder)
                .map(([category, n]) => `${t(`ops.task.${category}`)} ${n}`)
                .join(" · ")}`}
            </title>
          </g>
        ))}
        {labels.map((l) => (
          <text
            key={l.iata}
            data-testid="ops-label"
            className={l.strong ? "ops-label ops-label--strong" : "ops-label"}
            x={l.x}
            y={l.y}
            textAnchor={l.anchor}
            fontSize={11 * px}
            strokeWidth={3 * px}
          >
            {l.iata}
          </text>
        ))}
      </svg>
      <span className="ops-map-credit" data-testid="ops-map-credit">
        {t("ops.map.credit")}
      </span>
      <div className="ops-legend" data-testid="ops-legend">
        <span className="ops-legend-title">{t("ops.legend.attention")}</span>
        <ul className="ops-legend-group" aria-label={t("ops.legend.attention")}>
          {ATTENTION_LEGEND.map((k) => (
            <li key={k} className={`ops-legend--${k}`}>
              {k === "short" ? <svg className="ops-legend-crew" viewBox="-6 -6 12 12" aria-hidden="true"><CrewGlyph x={0} y={0} px={1.1} /></svg> : null}
              {t(`ops.legend.${k}`)}
            </li>
          ))}
        </ul>
        <ul className="ops-legend-group ops-legend-group--quiet">
          <li className="ops-legend--other">{t("ops.legend.other")}</li>
        </ul>
      </div>
    </div>
  );
}

