/* Operations Control Panel (knowledge-base/features/ops-control-panel.md §5). Design tokens come from tokens.css. */
.ops-app { min-height: 100vh; display: flex; flex-direction: column; }
/* The panel's plain controls in the Radar's outlined style. Each selector is wholly inside :where() so it weighs
   nothing: an attribute or :hover left outside would outrank a screen's own class (it boxed the radar's blips). */
:where(.ops-app :is(button, select, input[type="datetime-local"])) { padding: 6px 12px; border: 1px solid var(--border-secondary); border-radius: 6px; background: transparent; color: var(--text-secondary); font: inherit; font-size: 13px; line-height: 1.25; cursor: pointer; }
:where(.ops-app button:hover:not(:disabled)) { border-color: var(--accent-primary); color: var(--text-primary); }
:where(.ops-app button[aria-pressed="true"]) { background: var(--accent-primary-light); border-color: var(--accent-primary); color: var(--text-primary); }
:where(.ops-app button:disabled) { opacity: 0.45; cursor: default; }
:where(.ops-app select option) { background: var(--bg-secondary); color: var(--text-primary); }
/* Segmented controls: one outer border; square seams (global button radius must not show through). */
.ops-view, .ops-timeline-rule, .ops-lang {
  display: inline-flex; align-items: stretch; border: 1px solid var(--border-secondary); border-radius: 8px; overflow: hidden; background: var(--surface-card);
}
.ops-view > button, .ops-timeline-rule > button, .ops-lang > button {
  margin: 0; border: 0; border-radius: 0; border-right: 1px solid var(--border-secondary); background: transparent; color: var(--text-secondary); min-height: 32px; padding: 6px 12px; line-height: 1.25;
}
.ops-view > button:last-child, .ops-timeline-rule > button:last-child, .ops-lang > button:last-child { border-right: 0; }
.ops-view > button:hover:not(:disabled), .ops-timeline-rule > button:hover:not(:disabled), .ops-lang > button:hover:not(:disabled) {
  border-color: var(--border-secondary); color: var(--text-primary); background: var(--surface-hover);
}
.ops-view > button[aria-pressed="true"], .ops-timeline-rule > button[aria-pressed="true"], .ops-lang > button[aria-pressed="true"] {
  background: var(--accent-primary-light); border-color: var(--border-secondary); color: var(--text-primary); font-weight: 700;
}
.ops-header { display: flex; align-items: center; gap: 24px; padding: 8px 16px; border-bottom: 1px solid var(--border-primary); }
.ops-brand { display: flex; align-items: center; gap: 10px; font-weight: 600; white-space: nowrap; }
.ops-logo { height: 30px; width: auto; display: block; }
.ops-tenant-logo { height: 28px; width: 28px; border-radius: 8px; object-fit: cover; display: block; }
.ops-menu { display: flex; gap: 2px; }
.ops-menu a { padding: 6px 12px; border-radius: 6px; color: inherit; text-decoration: none; }
.ops-menu a[aria-current="page"] { background: var(--accent-primary-light); color: var(--text-primary); box-shadow: inset 0 -2px 0 var(--accent-primary); font-weight: 600; }
.ops-operations { padding: 12px 16px; display: flex; flex-direction: column; gap: 12px; }
.ops-clocks { display: flex; flex-wrap: wrap; gap: 12px; }
.ops-clock { display: inline-flex; align-items: baseline; gap: 10px; padding: 8px 16px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); }
.ops-clock-label { font: 600 12px var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--text-tertiary); }
.ops-clock-time { font: 700 22px var(--font-mono); color: var(--text-primary); }
.ops-timeline { display: flex; flex-direction: column; gap: 4px; padding: 10px 14px 18px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); color: var(--text-secondary); }
.ops-timeline-head { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin-bottom: 6px; }
